<script>
    
    $( document ).ready(function() {
        setInterval(comprueba_notificaciones,10000);
        setInterval(comprueba_alarmas,10000);
    });

   function comprueba_alarmas(){
        ajax = nuevoAjax();
        urlllamada="./accionesAjax.php?a=9";
        ajax.open("GET", urlllamada, true);
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                try {
                    var r = JSON.parse(ajax.responseText);
                    var banner = document.getElementById("banner_alarma");
                    var badge = document.getElementById("alarma_badge");
                    if (r && r.ok && r.total > 0) {
                        if (banner) { banner.style.display = "flex"; }
                        if (badge) { badge.style.display = "inline-flex"; badge.textContent = r.total > 9 ? "9+" : r.total; }
                        var texto = document.getElementById("banner_alarma_texto");
                        if (texto && r.alarmas && r.alarmas.length > 0) {
                            var a = r.alarmas[0];
                            texto.textContent = "🚨 Alarma " + (a.severidad === "asedio" ? "de asedio" : "sin revisar")
                                + " · " + a.fecha;
                        }
                    } else {
                        if (banner) { banner.style.display = "none"; }
                        if (badge) { badge.style.display = "none"; }
                    }
                } catch(e) { /* respuesta no JSON: ignorar */ }
            }
        };
        ajax.send(null);
   }

   function alarmas_leidas(){
        ajax = nuevoAjax();
        ajax.open("GET", "./accionesAjax.php?a=10", true);
        ajax.send(null);
        setTimeout(comprueba_alarmas, 300);
   }

   function enterpressed_buscar(e,c){
    var code = (e.keyCode ? e.keyCode : e.which);
    if(code == 13) { //Enter keycode
        buscarGlobal();
    }
   } 
   function buscarGlobal(){
       busca=document.getElementById("campo_buscar").value;
       location.href="?page=visitantes&buscador="+busca;
   }
   function comprueba_notificaciones(){
       
            ajax = nuevoAjax();
            urlllamada="./accionesAjax.php?a=1&local_id=<?= $_SESSION["local_id"]; ?>";
            ajax.open("GET", urlllamada, true);
            ajax.onreadystatechange = function () {
                if (ajax.readyState == 4) {
                    str=ajax.responseText;
                    
                    var res = str.substring(0, 5);
                    if(res=="truee"){
                        html='<div class="notification-content__title">Notificaciones</div>';
                        vaux=str.split("###");
                        for(i=1;i<vaux.length;i++){
                            vaux1=vaux[i].split("///");
                            
                            
                            //$return.=$cod_interno." - (".$nombre.")///".$descripcion_camara."///".$mode."///".$imagen1."///".$imagen2."###";
                            // Formato actual: persona_id///persona///camara_id///camara///mode///img1///img2///created
                            
                            persona_id=vaux1[0];
                            persona=vaux1[1];
                            camara_id=vaux1[2];
                            camara=vaux1[3];
                            mode=vaux1[4];
                            img1=vaux1[5];
                            img2=vaux1[6];
                            created=vaux1[7];

                            var camaraLink = (camara_id && camara_id != "0" && camara)
                                ? '<a class="text-theme-1 hover:underline" href="?page=camaras&id='+camara_id+'">'+camara+'</a>'
                                : camara;
                            var modeHtml = mode.replace(camara, camaraLink);

                            html+='<div class="cursor-pointer relative flex items-center ">'
                                html+='<div class="w-12 h-12 flex-none image-fit mr-1">'
                                    html+='<img alt="" class="rounded-full" src="'+img1+'">'
                                    html+='<div class="w-3 h-3 bg-theme-9 absolute right-0 bottom-0 rounded-full border-2 border-white"></div>'
                                html+='</div>';
                                html+='<div class="ml-2 overflow-hidden">';
                                    html+='<div class="flex items-center">';
                                        html+='<a href="?page=visitantes&mode=editar&id='+persona_id+'" class="font-medium truncate mr-5 text-theme-1 hover:underline">'+persona+'</a> ';
                                        html+='<div class="text-xs text-gray-500 ml-auto whitespace-no-wrap">'+created+'</div>';
                                    html+='</div>';
                                    html+='<div class="w-full truncate text-gray-600">'+modeHtml+'</div>';
                                html+='</div>';
                            html+='</div>';
                            
                            
                        }
                        document.getElementById("capa_notificaciones").innerHTML=html;
                    }
                }
            }
            ajax.send(null);
       
   }
   
   function notificaciones_leidas(){
        ajax = nuevoAjax();
        urlllamada="./accionesAjax.php?a=2&local_id=<?= $_SESSION["local_id"]; ?>";
        ajax.open("GET", urlllamada, true);
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                document.getElementById("campanita_notificaciones").setAttribute("class","dropdown-toggle notification notification--light cursor-pointer");
            }
        }
        ajax.send(null);
   }
   
   
</script>